#!/usr/bin/env python3
"""
Fetch all PR conversation comments + reviews + review threads (inline threads)
for the PR associated with the current git branch, by shelling out to:

  gh api graphql

Requires:
  - `gh auth login` already set up
  - current branch has an associated (open) PR

Usage:
  python fetch_comments.py > pr_comments.json
"""

from __future__ import annotations

import json
import subprocess
import sys
from typing import Any

QUERY = """\
query(
  $owner: String!,
  $repo: String!,
  $number: Int!,
  $commentsCursor: String,
  $reviewsCursor: String,
  $threadsCursor: String
) {
  repository(owner: $owner, name: $repo) {
    pullRequest(number: $number) {
      number
      url
      title
      state

      # Top-level "Conversation" comments (issue comments on the PR)
      comments(first: 100, after: $commentsCursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          body
          createdAt
          updatedAt
          author { login }
        }
      }

      # Review submissions (Approve / Request changes / Comment), with body if present
      reviews(first: 100, after: $reviewsCursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          state
          body
          submittedAt
          author { login }
        }
      }

      # Inline review threads (grouped), includes resolved state
      reviewThreads(first: 100, after: $threadsCursor) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id
          isResolved
          isOutdated
          path
          line
          diffSide
          startLine
          startDiffSide
          originalLine
          originalStartLine
          resolvedBy { login }
          comments(first: 100) {
            nodes {
              id
              body
              createdAt
              updatedAt
              author { login }
            }
          }
        }
      }
    }
  }
}
"""


def _run(cmd: list[str], stdin: str | None = None) -> str:
    p = subprocess.run(cmd, input=stdin, capture_output=True, text=True)
    if p.returncode != 0:
        raise RuntimeError(f"Command failed: {' '.join(cmd)}\n{p.stderr}")
    return p.stdout


def _run_json(cmd: list[str], stdin: str | None = None) -> dict[str, Any]:
    out = _run(cmd, stdin=stdin)
    try:
        return json.loads(out)
    except json.JSONDecodeError as e:
        raise RuntimeError(f"Failed to parse JSON from command output: {e}\nRaw:\n{out}") from e


def _ensure_gh_authenticated() -> None:
    try:
        _run(["gh", "auth", "status"])
    except RuntimeError:
        print("run `gh auth login` to authenticate the GitHub CLI", file=sys.stderr)
        raise RuntimeError("gh auth status failed; run `gh auth login` to authenticate the GitHub CLI") from None


def gh_pr_view_json(fields: str) -> dict[str, Any]:
    # fields is a comma-separated list like: "number,headRepositoryOwner,headRepository"
    return _run_json(["gh", "pr", "view", "--json", fields])


def get_current_pr_ref() -> tuple[str, str, int]:
    """
    Resolve the PR for the current branch (whatever gh considers associated).
    Works for cross-repo PRs too, by reading head repository owner/name.
    """
    pr = gh_pr_view_json("number,headRepositoryOwner,headRepository")
    owner = pr["headRepositoryOwner"]["login"]
    repo = pr["headRepository"]["name"]
    number = int(pr["number"])
    return owner, repo, number


def gh_api_graphql(
    owner: str,
    repo: str,
    number: int,
    comments_cursor: str | None = None,
    reviews_cursor: str | None = None,
    threads_cursor: str | None = None,
) -> dict[str, Any]:
    """
    Call `gh api graphql` using -F variables, avoiding JSON blobs with nulls.
    Query is passed via stdin using query=@- to avoid shell newline/quoting issues.
    """
    cmd = [
        "gh",
        "api",
        "graphql",
        "-F",
        "query=@-",
        "-F",
        f"owner={owner}",
        "-F",
        f"repo={repo}",
        "-F",
        f"number={number}",
    ]
    if comments_cursor:
        cmd += ["-F", f"commentsCursor={comments_cursor}"]
    if reviews_cursor:
        cmd += ["-F", f"reviewsCursor={reviews_cursor}"]
    if threads_cursor:
        cmd += ["-F", f"threadsCursor={threads_cursor}"]

    return _run_json(cmd, stdin=QUERY)


def fetch_all(owner: str, repo: str, number: int) -> dict[str, Any]:
    conversation_comments: list[dict[str, Any]] = []
    reviews: list[dict[str, Any]] = []
    review_threads: list[dict[str, Any]] = []

    comments_cursor: str | None = None
    reviews_cursor: str | None = None
    threads_cursor: str | None = None

    pr_meta: dict[str, Any] | None = None

    while True:
        payload = gh_api_graphql(
            owner=owner,
            repo=repo,
            number=number,
            comments_cursor=comments_cursor,
            reviews_cursor=reviews_cursor,
            threads_cursor=threads_cursor,
        )

        if "errors" in payload and payload["errors"]:
            raise RuntimeError(f"GitHub GraphQL errors:\n{json.dumps(payload['errors'], indent=2)}")

        pr = payload["data"]["repository"]["pullRequest"]
        if pr_meta is None:
            pr_meta = {
                "number": pr["number"],
                "url": pr["url"],
                "title": pr["title"],
                "state": pr["state"],
                "owner": owner,
                "repo": repo,
            }

        c = pr["comments"]
        r = pr["reviews"]
        t = pr["reviewThreads"]

        conversation_comments.extend(c.get("nodes") or [])
        reviews.extend(r.get("nodes") or [])
        review_threads.extend(t.get("nodes") or [])

        comments_cursor = c["pageInfo"]["endCursor"] if c["pageInfo"]["hasNextPage"] else None
        reviews_cursor = r["pageInfo"]["endCursor"] if r["pageInfo"]["hasNextPage"] else None
        threads_cursor = t["pageInfo"]["endCursor"] if t["pageInfo"]["hasNextPage"] else None

        if not (comments_cursor or reviews_cursor or threads_cursor):
            break

    assert pr_meta is not None
    return {
        "pull_request": pr_meta,
        "conversation_comments": conversation_comments,
        "reviews": reviews,
        "review_threads": review_threads,
    }


def main() -> None:
    _ensure_gh_authenticated()
    owner, repo, number = get_current_pr_ref()
    result = fetch_all(owner, repo, number)
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
# High-Level Implementation Plan: Kernel-Driven Agent Harness

## 1. Objective

Build a production-oriented agent harness with:

- a trusted control plane implemented as Go microservices;
- Python used only for declarative agent configuration and prompt composition;
- provider-neutral reasoning contracts;
- deterministic workflow control;
- strict separation between model proposals and kernel authority;
- isolated execution and independent verification;
- immutable, auditable artifacts and workflow events.

The harness must enforce the following invariant:

> Models may propose actions and changes. Only the Go kernel may authorize, execute, verify, approve, or advance workflow state.

---

# 2. Core Workflow

Implement the following workflow:

```text
User request
    ↓
Specification proposal
    ↓
Human specification approval
    ↓
Task graph proposal
    ↓
Kernel validation
    ↓
Human task-plan approval
    ↓
Bounded implementation proposal
    ↓
Controlled execution in isolated workspace
    ↓
Independent verification
    ↓
Independent review
    ↓
Human approval
    ↓
Draft pull request
```

The first release must not automatically merge pull requests or deploy changes.

---

# 3. System Boundaries

## 3.1 Go control plane

Go services own all trusted behavior:

- workflow and task state;
- state transitions;
- authorization;
- policy enforcement;
- proposal validation;
- task scheduling;
- resource leases;
- Git worktree management;
- controlled file mutation;
- command execution;
- verification;
- evidence collection;
- approval enforcement;
- audit events;
- artifact metadata;
- pull-request creation.

## 3.2 Python agent configuration

Python defines:

- agent roles;
- prompt templates;
- context-selection preferences;
- model capability requirements;
- model parameter preferences;
- allowed tool-request types;
- output contract references;
- stage-specific agent configuration.

Python must not:

- update workflow state;
- access kernel databases;
- invoke Git directly;
- execute task commands;
- approve work;
- widen task scope;
- create resource leases;
- publish branches;
- open pull requests;
- provide authoritative test evidence.

Python configuration must compile into a canonical, immutable JSON manifest before being registered with the Go control plane.

---

# 4. Initial Architectural Style

Use a monorepo with separately deployable Go services.

```text
agent-harness/
├── go/
│   ├── cmd/
│   │   ├── api-service/
│   │   ├── workflow-service/
│   │   ├── agent-registry/
│   │   ├── reasoning-gateway/
│   │   ├── execution-service/
│   │   └── verification-service/
│   ├── internal/
│   │   ├── workflow/
│   │   ├── reasoning/
│   │   ├── policy/
│   │   ├── execution/
│   │   ├── verification/
│   │   ├── approval/
│   │   ├── artifacts/
│   │   └── events/
│   └── pkg/
│
├── python/
│   ├── src/harness_agents/
│   ├── agents/
│   ├── prompts/
│   └── tests/
│
├── proto/
│   └── harness/
│       ├── reasoning/v1/
│       ├── workflow/v1/
│       ├── execution/v1/
│       └── events/v1/
│
├── schemas/
│   └── agent-manifest-v1.schema.json
│
├── migrations/
├── deploy/
├── docs/
└── tests/
```

Keep business logic in Go packages that can be tested without starting network services.

Do not create additional microservices unless a clear ownership, scaling, security, or deployment boundary requires one.

---

# 5. Initial Go Services

## 5.1 API Service

Responsibilities:

- expose CLI- and UI-facing HTTP APIs;
- authenticate users;
- accept commands;
- expose workflow and task status;
- expose pending approvals;
- forward commands to the workflow service.

Initial endpoints:

```text
POST /runs
GET  /runs/{run_id}
POST /runs/{run_id}/specification
POST /runs/{run_id}/specification/approve
POST /runs/{run_id}/task-graph
POST /runs/{run_id}/task-graph/approve
POST /tasks/{task_id}/retry
POST /tasks/{task_id}/approve
POST /tasks/{task_id}/reject
POST /runs/{run_id}/cancel
```

## 5.2 Workflow Service

Responsibilities:

- own run and task lifecycle state;
- enforce legal transitions;
- evaluate task readiness;
- coordinate stage progression;
- enforce retry limits;
- persist commands and resulting events;
- dispatch long-running activities.

The workflow service must not call model providers directly.

## 5.3 Agent Registry

Responsibilities:

- accept compiled agent manifests;
- validate manifests against JSON Schema;
- canonicalize JSON;
- calculate SHA-256 digests;
- register immutable agent versions;
- return manifests by name, version, or digest;
- reject mutable version replacement.

## 5.4 Reasoning Gateway

Responsibilities:

- receive typed reasoning requests;
- load an immutable agent manifest;
- assemble model input;
- route to a provider adapter;
- decode structured model output;
- return an untrusted proposal;
- record model usage and invocation metadata.

The reasoning gateway must not:

- mutate workflow state;
- execute proposed file changes;
- mark evidence as verified;
- approve proposals;
- widen task scope.

## 5.5 Execution Service

Responsibilities:

- create isolated Git worktrees;
- apply accepted file-change proposals;
- enforce writable-path policies;
- prevent path traversal and symlink escapes;
- run approved commands;
- create candidate commits;
- report actual changed files;
- enforce CPU, memory, storage, network, and timeout limits.

## 5.6 Verification Service

Responsibilities:

- check out the exact candidate commit in a clean environment;
- run kernel-selected checks;
- record command, exit code, timing, and output digest;
- map evidence to acceptance criteria;
- produce scope and verification reports;
- store logs and evidence artifacts.

Verification must be independent from the implementation model and implementation workspace.

# Architecture

The harness follows a proposal/kernel split. Models and Python configuration
may describe requested work; only a Go kernel may authorize, execute, verify,
approve, or advance state.

Phase 0–1 contains six empty Go command boundaries: API, workflow, agent
registry, reasoning gateway, execution, and verification. They compile but
start no server. Shared business rules live in handwritten packages, while
generated Protobuf packages remain transport-only.

Python is an offline authoring tool. It compiles declarative definitions into
immutable canonical JSON and has no workflow, database, Git, command execution,
credential, approval, publication, or task-scope authority.

PostgreSQL, artifact storage, gRPC servers, workflow runtime, leases, worktrees,
providers, file mutation, verification execution, and pull-request publication
are architectural commitments or later-phase candidates, not implemented here.
